    start_utc: i64,
    end_utc: i64,
    limit: usize,
) -> Result<Vec<i64>, CaldavAuthError> {
    let start_date = utc_date(start_utc);
    let end_date = utc_date(end_utc);
    let ids: Vec<i64> = sqlx::query_scalar(
        "SELECT id FROM events
          WHERE calendar_id = ?
