        .event(calendar.calendar_id, resource.event_id)
        .await
    {
        Ok(Some(event)) => event,
        Ok(None) => return dav_resource_not_found(),
        Err(_) => return dav_server_error(),
    };
    let Some((_, current_etag)) = ical_and_etag(resource, &event, DavReadAccess::Details) else {
        return dav_resource_not_found();
    };
    if !etag_matches(if_match, &current_etag) {
        return (StatusCode::PRECONDITION_FAILED, "precondition failed").into_response();
    }

    let body = match axum::body::to_bytes(request.into_body(), query::MAX_BODY_BYTES).await {
        Ok(body) => body,
        Err(_) => return dav_bad_request("request body too large"),
    };
    let body_str = match std::str::from_utf8(&body) {
        Ok(value) => value,
        Err(_) => return dav_bad_request("request body must be UTF-8"),
    };
    let parsed = match parse_calendar(body_str, IcsParserLimits::default()) {
        Ok(parsed) => parsed,
        Err(_) => return dav_bad_request("invalid calendar data"),
    };
    if parsed.events.len() != 1 {
        return dav_bad_request("exactly one VEVENT is required");
    }
    let incoming = &parsed.events[0];
    if incoming.rrule.is_some() || incoming.recurrence_id.is_some() {
        return dav_bad_request("recurring events are not supported");
    }
    let timing = match &incoming.timing {
        crate::ics::NormalizedTiming::Timed {
            starts_at,
            ends_at,
            timezone,
        } => EventTiming::Timed {
            start_utc: starts_at.timestamp(),
            end_utc: ends_at.timestamp(),
            timezone: timezone.clone().unwrap_or_else(|| "UTC".to_owned()),
        },
        crate::ics::NormalizedTiming::AllDay {
            start_date,
            end_date,
        } => EventTiming::AllDay {
            start_date: start_date.format("%Y-%m-%d").to_string(),
            end_date: end_date.format("%Y-%m-%d").to_string(),
        },
    };
    if timing_end_not_after_start(&timing) {
        return dav_bad_request("event end must be after start");
    }
    let status = match incoming.status.as_deref() {
        Some("TENTATIVE") => EventStatus::Tentative,
        Some("CANCELLED") => EventStatus::Cancelled,
        _ => EventStatus::Confirmed,
    };
    if incoming.summary.trim().is_empty() {
        return dav_bad_request("SUMMARY is required");
    }

    let mutation = EventMutation {
        title: incoming.summary.clone(),
        description: incoming.description.clone(),
        location: incoming.location.clone(),
        status,
        timing,
    };
    let event_service = EventService::new_at(accounts.pool().clone(), accounts.now());
    let projection = match event_service
        .update(
            session.user_id,
            false,
            calendar.calendar_id,
            resource.event_id,
            EventChange {
                expected_version: event.version,
                target_calendar_id: calendar.calendar_id,
                event: mutation,
            },
        )
        .await
    {
        Ok(projection) => projection,
        Err(EventServiceError::Conflict { .. }) => {
            return (StatusCode::PRECONDITION_FAILED, "precondition failed").into_response();
        }
        Err(EventServiceError::NotFound) => return dav_resource_not_found(),
        Err(EventServiceError::ReadOnly) => return dav_resource_not_found(),
        Err(_) => return dav_server_error(),
    };

    let event_record = match EventRepository::new(accounts.pool().clone())
        .event(calendar.calendar_id, projection.id)
        .await
    {
        Ok(Some(event_record)) => event_record,
        _ => return dav_server_error(),
    };
    let Some((ical, etag)) = ical_and_etag(resource, &event_record, DavReadAccess::Details) else {
        return dav_server_error();
    };
    (
        StatusCode::OK,
        [
            (header::ETAG, etag.as_str()),
            (header::CONTENT_TYPE, "text/calendar; charset=utf-8"),
        ],
        ical,
    )
        .into_response()
}

