    EventMutation {
        title: "Planning".to_owned(),
        description: Some("Quarterly planning".to_owned()),
        location: Some("Room 1".to_owned()),
        status: EventStatus::Confirmed,
        timing: EventTiming::Timed {
            start_utc: 1_768_435_200,
